import React, { useState, useEffect } from "react";
import axios from "axios";
import { useCart } from "../components/CartContext";
import { useNavigate, useLocation } from "react-router-dom";
import { toast } from 'react-toastify';

const groupByCategory = (products) => {
  return products.reduce((acc, product) => {
    (acc[product.category] = acc[product.category] || []).push(product);
    return acc;
  }, {});
};

const Products = () => {
  const [products, setProducts] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [file, setFile] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showViewModal, setShowViewModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [categories, setCategories] = useState([]);
  const [brands, setBrands] = useState([]);
  const [categoryFilter, setCategoryFilter] = useState("");
  const [brandFilter, setBrandFilter] = useState("");
  const [priceFilter, setPriceFilter] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    category: "",
    price: "",
    brand: "",
  });

  const navigate = useNavigate();
  const location = useLocation();
  const role = localStorage.getItem("role");

  useEffect(() => {
    axios.get("http://localhost:5000/api/users/allcategories").then(res => setCategories(res.data)).catch(console.error);
    axios.get("http://localhost:5000/api/users/allbrands").then(res => setBrands(res.data)).catch(console.error);
    axios.get("http://localhost:5000/api/users/allproducts").then(res => setProducts(res.data)).catch(console.error);
  }, []);

  // Set brand filter from query param on mount
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const brand = params.get('brand');
    const category = params.get('category');
    if (brand) setBrandFilter(brand);
    if (category) setCategoryFilter(category);
  }, [location.search]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleAddProduct = async (e) => {
    e.preventDefault();
    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    formDataToSend.append("category", formData.category);
    formDataToSend.append("price", formData.price);
    formDataToSend.append("brand", formData.brand);
    formDataToSend.append("image", file);
    try {
       const token = localStorage.getItem("token");
      const res = await axios.post("http://localhost:5000/api/users/addproduct", formDataToSend, {
        headers: { "Content-Type": "multipart/form-data" ,
           "Authorization": `Bearer ${token}`,
        },
      });
      setProducts([res.data, ...products]);
      setFormData({ name: "", category: "", price: "", brand: "" });
      setFile(null);
      setShowForm(false);
    } catch (err) {
      toast.error(err.response?.data?.message || "Error adding product");
    }
  };

 const handleDelete = async (id) => {
  if (!window.confirm("Are you sure you want to delete this product?")) return;

  try {
    const token = localStorage.getItem("token"); // Get the token

    await axios.delete(`http://localhost:5000/api/users/product/${id}`, {
      headers: {
        Authorization: `Bearer ${token}`, // fRequired for verifyToken
      },
    });

    setProducts(products.filter((p) => p._id !== id));
  } catch (error) {
    console.error("Failed to delete product:", error.response?.data || error.message);
    toast.error("Failed to delete product");
  }
};


 const { addToCart, cartItems } = useCart(); // make sure addToCart is included!

const handleAddToCart = (product) => {
  const token = localStorage.getItem("token");
  if (!token) {
    navigate("/login");
    return;
  }
  addToCart(product);
};


  const filteredProducts = products.filter((product) => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter ? product.category.toLowerCase() === categoryFilter.toLowerCase() : true;
    const matchesBrand = brandFilter ? product.brand.toLowerCase() === brandFilter.toLowerCase() : true;
    const matchesPrice = (() => {
      if (!priceFilter) return true;
      const price = Number(product.price);
      if (priceFilter === "0-1000") return price >= 0 && price <= 1000;
      if (priceFilter === "1000-1500") return price > 1000 && price <= 1500;
      if (priceFilter === "1500-2000") return price > 1500 && price <= 2000;
      if (priceFilter === "2000-3000") return price > 2000 && price <= 3000;
      if (priceFilter === "3000+") return price > 3000;
      return true;
    })();
    return matchesSearch && matchesCategory && matchesBrand && matchesPrice;
  });

  return (
    <div style={{ background: "var(--color-bg)", minHeight: "100vh", color: "var(--color-text)", fontFamily: "'Inter', Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginTop: "20px", color: "var(--color-primary)" }}>Products</h1>

      <div className="filter-bar" style={{ background: "var(--color-surface)", borderRadius: "12px", padding: "20px", margin: "0 auto 24px auto", maxWidth: "1200px", boxShadow: "0 2px 8px rgba(26,35,126,0.08)" }}>
        <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)} style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Categories</option>
          {categories.map((c) => <option key={c._id} value={c.name}>{c.name}</option>)}
        </select>

        <select value={brandFilter} onChange={(e) => setBrandFilter(e.target.value)} style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Brands</option>
          {brands.map((b) => <option key={b._id} value={b.name}>{b.name}</option>)}
        </select>

        <select value={priceFilter} onChange={(e) => setPriceFilter(e.target.value)} style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Prices</option>
          <option value="0-1000">₹0 - ₹1000</option>
          <option value="1000-1500">₹1000 - ₹1500</option>
          <option value="1500-2000">₹1500 - ₹2000</option>
          <option value="2000-3000">₹2000 - ₹3000</option>
          <option value="3000+">₹3000+</option>
        </select>

        <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }} />

        {role === "admin" && (
          <button onClick={() => setShowForm(true)} style={{ background: "var(--color-primary)", color: "#fff", border: "none", borderRadius: "8px", padding: "8px 18px", fontWeight: 600, fontSize: "15px", marginLeft: "8px", cursor: "pointer" }}>Add Product</button>
        )}
        <button onClick={() => {
          setCategoryFilter("");
          setBrandFilter("");
          setPriceFilter("");
          setSearchTerm("");
        }} style={{ background: "var(--color-border)", color: "var(--color-text)", border: "none", borderRadius: "8px", padding: "8px 18px", fontWeight: 600, fontSize: "15px", marginLeft: "8px", cursor: "pointer" }}>Reset</button>
      </div>

      {showForm && role === "admin" && (
        <form className="add-form" onSubmit={handleAddProduct} style={{ background: "var(--color-surface)", color: "var(--color-text)", borderRadius: "12px", boxShadow: "0 2px 8px rgba(26,35,126,0.08)", padding: "24px", margin: "0 auto 24px auto", maxWidth: "600px", display: "flex", flexDirection: "column", gap: "12px" }}>
          <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Product Name" required style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <select name="category" value={formData.category} onChange={handleChange} required style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "10px", fontSize: "15px" }}>
            <option value="">Select Category</option>
            {categories.map((c) => <option key={c._id} value={c.name}>{c.name}</option>)}
          </select>
          <select name="brand" value={formData.brand} onChange={handleChange} required style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "10px", fontSize: "15px" }}>
            <option value="">Select Brand</option>
            {brands.map((b) => <option key={b._id} value={b.name}>{b.name}</option>)}
          </select>
          <input type="number" name="price" value={formData.price} onChange={handleChange} placeholder="Price" required style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <input type="file" onChange={handleFileChange} required style={{ background: "var(--color-bg)", color: "var(--color-text)", border: "1px solid var(--color-border)", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <button type="submit" style={{ background: "var(--color-primary)", color: "#fff", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", marginRight: "10px", cursor: "pointer" }}>Submit</button>
          <button type="button" onClick={() => setShowForm(false)} style={{ background: "var(--color-danger)", color: "#fff", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", cursor: "pointer" }}>Cancel</button>
        </form>
      )}
{cartItems.length > 0 && (
  <button className="floating-cart-btn" onClick={() => navigate("/cart")}>🛒 {cartItems.length}</button>
)}


      <div className="product-grid" style={{ background: "var(--color-surface)", borderRadius: "12px", padding: "24px 0", boxShadow: "0 2px 8px rgba(26,35,126,0.06)" }}>
        {filteredProducts.map((product) => (
          <div key={product._id} className="square-card" style={{ background: "var(--color-surface)", color: "var(--color-text)", borderRadius: "12px", boxShadow: "0 4px 16px rgba(26,35,126,0.08)", border: "1px solid var(--color-border)" }}>
            <img src={`http://localhost:5000/uploads/${product.image}`} alt={product.name} className="square-img" style={{ background: "var(--color-bg)" }} />
            <div className="square-info">
              <h4 style={{ color: "var(--color-primary)" }}>{product.name}</h4>
              <div className="product-meta">{product.category}</div>
              <div className="product-meta">{product.brand}</div>
              <div className="product-meta">₹{product.price}</div>
              <div className="button-row">
                <button className="square-btn view" style={{ background: "var(--color-accent)", color: "#fff" }} onClick={() => { setSelectedProduct(product); setShowViewModal(true); }}>View</button>
                {role === "admin" && (
                  <button className="square-btn delete" style={{ background: "var(--color-danger)", color: "#fff" }} onClick={() => handleDelete(product._id)}>Delete</button>
                )}
              </div>
              <button className="square-btn view" style={{ background: "var(--color-primary)", color: "#fff", marginTop: "10px" }} onClick={() => handleAddToCart(product)}>Add to Cart 🛒</button>
            </div>
          </div>
        ))}
      </div>

      {showViewModal && selectedProduct && (
        <div className="modal-overlay" style={{ background: "rgba(26,35,126,0.95)" }}>
          <div className="modal-box" style={{ background: "var(--color-surface)", color: "var(--color-text)", borderRadius: "12px", boxShadow: "0 4px 24px rgba(26,35,126,0.12)", padding: "32px" }}>
            <h2 style={{ color: "var(--color-primary)" }}>{selectedProduct.name}</h2>
            <img src={`http://localhost:5000/uploads/${selectedProduct.image}`} alt={selectedProduct.name} className="square-img" style={{ background: "var(--color-bg)" }} />
            <p>Category: {selectedProduct.category}</p>
            <p>Brand: {selectedProduct.brand}</p>
            <p>Price: ₹{selectedProduct.price}</p>
            <button onClick={() => setShowViewModal(false)} style={{ background: "var(--color-border)", color: "var(--color-text)", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", cursor: "pointer", marginTop: "16px" }}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Products;
